use kyberia_domain::{identity::{FloorId, FrameId}, spatial::Point2, units::{CoordinateMeters, Meters, Radians}};
use kyberia_geometry_adapter::{ValidatedPolygon, OffsetOptions, OffsetDirection};

#[unsafe(no_mangle)]
pub extern "C" fn square_offset_area(direction: i32, translation: f64) -> f64 {
    let points = [(0.0,0.0),(10.0,0.0),(10.0,10.0),(0.0,10.0),(0.0,0.0)].into_iter().map(|(x,y)| Point2 {
        x: CoordinateMeters::new(x + translation).unwrap(),
        y: CoordinateMeters::new(y + translation).unwrap(),
    }).collect();
    let polygon = ValidatedPolygon::new(FloorId::from_bytes([1;16]).unwrap(),FrameId::from_bytes([2;16]).unwrap(),points,vec![]).unwrap().as_multipolygon();
    let distance = match direction {
        0 => OffsetDirection::Outward(Meters::new(0.0).unwrap()),
        1 => OffsetDirection::Outward(Meters::new(1.0).unwrap()),
        -1 => OffsetDirection::Inward(Meters::new(1.0).unwrap()),
        -2 => OffsetDirection::Inward(Meters::new(6.0).unwrap()),
        _ => return f64::NAN,
    };
    let options=OffsetOptions::new(distance,Radians::new(std::f64::consts::PI/16.0).unwrap()).unwrap();
    let result=polygon.offset(options).unwrap();
    result.polygons().iter().map(|p| {
        let origin=p.exterior()[0];
        let area = |ring: &[Point2]| ring.windows(2).map(|pair| {
            let a=(pair[0].x.get()-origin.x.get(),pair[0].y.get()-origin.y.get());
            let b=(pair[1].x.get()-origin.x.get(),pair[1].y.get()-origin.y.get());
            a.0*b.1-b.0*a.1
        }).sum::<f64>().abs()/2.0;
        area(p.exterior()) - p.holes().iter().map(|r| area(r)).sum::<f64>()
    }).sum()
}

#[unsafe(no_mangle)]
pub extern "C" fn mixed_scale_rejected(translation: f64) -> u32 {
    use kyberia_geometry_adapter::{ValidatedMultiPolygon, OffsetError};
    let floor=FloorId::from_bytes([1;16]).unwrap();
    let frame=FrameId::from_bytes([2;16]).unwrap();
    let rectangle=|x0:f64,y0:f64,x1:f64,y1:f64| {
        let points=[(x0,y0),(x1,y0),(x1,y1),(x0,y1),(x0,y0)].into_iter().map(|(x,y)| Point2 {
            x:CoordinateMeters::new(x+translation).unwrap(),
            y:CoordinateMeters::new(y+translation).unwrap(),
        }).collect();
        ValidatedPolygon::new(floor,frame,points,vec![]).unwrap()
    };
    let input=ValidatedMultiPolygon::new(floor,frame,vec![rectangle(-1000.0,-1000.0,0.0,0.0),rectangle(2e-6,2e-6,2.1e-6,2.1e-6)]).unwrap();
    let options=OffsetOptions::new(OffsetDirection::Outward(Meters::new(1e-5).unwrap()),Radians::new(0.25).unwrap()).unwrap();
    u32::from(input.offset(options)==Err(OffsetError::UnsupportedCoordinateResolution))
}

